def processQueries(c, connections, queries):
    parent = list(range(c + 1))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for u, v in connections:
        ru, rv = find(u), find(v)
        if ru != rv:
            parent[ru] = rv

    # members of each grid in ascending order
    members = {}
    for i in range(1, c + 1):
        members.setdefault(find(i), []).append(i)
    ptr = {r: 0 for r in members}

    offline = [False] * (c + 1)
    ans = []
    for t, x in queries:
        if t == 2:
            offline[x] = True
        else:
            if not offline[x]:
                ans.append(x)
            else:
                r = find(x)
                lst = members[r]
                p = ptr[r]
                while p < len(lst) and offline[lst[p]]:
                    p += 1
                ptr[r] = p
                ans.append(lst[p] if p < len(lst) else -1)
    return ans
